/**
 * Runtime Auth Environment Validator
 *
 * This utility validates that the auth URL matches the expected environment
 * and detects cross-environment configuration issues at runtime.
 *
 * Bug Reference:
 * - Date: Before Nov 16, 2025
 * - Commit: ab5f5300d7 (PR #13468)
 * - Issue: dev.docbits.com was posting to production auth
 * - Root Cause: GitHub Actions didn't export .env variables to $GITHUB_ENV
 *
 * Build-Time Issue:
 * This validator helps detect if APP_VUE_BRANCH and APP_VUE_STAGE were not
 * properly exported during build (process.env would be undefined).
 * The prebuild validator (scripts/validate-build-env.js) catches this early,
 * but this runtime validator provides additional safety at app startup.
 *
 * This utility provides runtime warnings if mismatches are detected.
 */

interface AuthEnvironmentConfig {
  branch: string;
  stage: string;
  authUrl: string;
  apiUrl: string;
  isLocalDev: boolean;
}

/**
 * Get the current auth environment configuration
 */
export function getAuthEnvironmentConfig(): AuthEnvironmentConfig {
  const branch = process.env.APP_VUE_BRANCH || '';
  const stage = process.env.APP_VUE_STAGE || '';
  const isLocalDev = stage === 'local';

  let auth_branch = '';
  if (branch && !branch.startsWith('pre-prod') && branch !== 'prod') {
    auth_branch = branch + '.';
  }

  const authUrl = isLocalDev ? 'http://localhost:5001' : `https://${auth_branch}auth.docbits.com`;
  const apiUrl = `https://${auth_branch}api.docbits.com`;

  return {
    branch,
    stage,
    authUrl,
    apiUrl,
    isLocalDev,
  };
}

/**
 * Validate auth environment configuration and return validation result
 */
export function validateAuthEnvironment(): {
  isValid: boolean;
  warnings: string[];
  errors: string[];
  buildTimeIssueDetected?: boolean;
} {
  const config = getAuthEnvironmentConfig();
  const warnings: string[] = [];
  const errors: string[] = [];
  let buildTimeIssueDetected = false;

  // Check 0: Critical - Missing environment variables at build time
  // This check is only relevant for PRODUCTION builds (deployed environments)
  // In local development (NODE_ENV=development), these variables are optional
  // because the developer is running locally with `npm start` or `quasar dev`
  const isProductionBuild = process.env.NODE_ENV === 'production';
  const isLocalhost = typeof window !== 'undefined' && window.location.hostname === 'localhost';

  // Only flag as build-time error if:
  // 1. It's a production build AND
  // 2. We're NOT on localhost
  // For local development, missing env vars are expected and OK
  if (isProductionBuild && !isLocalhost) {
    if (!config.branch || config.branch === '') {
      buildTimeIssueDetected = true;
      errors.push(
        `CRITICAL BUILD ERROR: APP_VUE_BRANCH is not set. ` +
        `This indicates GitHub Actions did not export environment variables correctly. ` +
        `Check: scripts/validate-build-env.js and .github/workflows/deployment.yaml ` +
        `The build should have failed at npm run build (prebuild script).`
      );
    }

    if (!config.stage || config.stage === '') {
      buildTimeIssueDetected = true;
      errors.push(
        `CRITICAL BUILD ERROR: APP_VUE_STAGE is not set. ` +
        `This indicates GitHub Actions did not export environment variables correctly.`
      );
    }
  }

  // Check 1: Localhost consistency
  if (config.isLocalDev) {
    if (!config.authUrl.includes('localhost:5001')) {
      errors.push(
        `Local development: AUTH_URL should be http://localhost:5001 but got ${config.authUrl}`
      );
    }
  }

  // Check 2: Non-prod should not use production auth (main bug prevention)
  if (config.stage !== 'prod' && !config.isLocalDev) {
    if (config.authUrl === 'https://auth.docbits.com' && config.stage !== 'prod') {
      errors.push(
        `Critical: ${config.stage} environment is using production auth (https://auth.docbits.com). ` +
        `Expected: https://${config.branch}.auth.docbits.com. ` +
        `This is the authentication environment mismatch bug. ` +
        `Verify APP_VUE_BRANCH="${config.branch}" is correctly set in GitHub Actions.`
      );
      buildTimeIssueDetected = true;
    }
  }

  // Check 3: API and Auth URL consistency
  if (!config.isLocalDev) {
    const getExpectedBranch = (url: string) => {
      const match = url.match(/https:\/\/([^.]*)\./);
      return match ? match[1] : '';
    };

    const authBranch = getExpectedBranch(config.authUrl);
    const apiBranch = getExpectedBranch(config.apiUrl);

    if (authBranch !== apiBranch) {
      errors.push(
        `Inconsistent environment prefixes: API uses ${apiBranch || 'production'}, ` +
        `Auth uses ${authBranch || 'production'}`
      );
    }
  }

  // Check 4: Stage/Branch mismatch
  if (config.branch && config.stage) {
    if (config.branch !== config.stage && !config.branch.includes('-')) {
      warnings.push(
        `APP_VUE_BRANCH (${config.branch}) differs from APP_VUE_STAGE (${config.stage})`
      );
    }
  }

  // Check 5: Hostname-to-environment consistency (runtime detection)
  if (!config.isLocalDev && typeof window !== 'undefined') {
    const hostname = window.location.hostname;
    const expectedBranch = config.branch;

    // Extract environment from hostname (e.g., dev.docbits.com -> dev)
    const hostnameMatch = hostname.match(/^([a-z0-9-]+)\.docbits\.com$/);
    const hostnameEnv = hostnameMatch ? hostnameMatch[1] : 'production';

    // For production, hostname should be just docbits.com (no prefix)
    if (expectedBranch === 'prod' || expectedBranch === '') {
      if (hostnameEnv !== 'production' && hostname !== 'docbits.com') {
        warnings.push(
          `Hostname mismatch: App accessed via ${hostname} but ` +
          `configured for production environment. ` +
          `Is this intentional?`
        );
      }
    } else {
      // For non-prod environments, hostname should match branch
      if (hostnameEnv !== expectedBranch) {
        warnings.push(
          `Hostname-to-environment mismatch: Hostname ${hostname} suggests ` +
          `${hostnameEnv} environment but APP_VUE_BRANCH is ${expectedBranch}`
        );
      }
    }
  }

  const isValid = errors.length === 0;

  return {
    isValid,
    warnings,
    errors,
    buildTimeIssueDetected,
  };
}

/**
 * Initialize auth environment validation on app startup
 * Log configuration and warnings in development mode
 * Also validates in production to catch critical misconfigurations
 */
export function initializeAuthEnvironmentValidator() {
  const config = getAuthEnvironmentConfig();
  const validation = validateAuthEnvironment();

  // Log current configuration (dev and production)
  const configLog = {
    branch: config.branch || '(NOT SET)',
    stage: config.stage || '(NOT SET)',
    authUrl: config.authUrl,
    apiUrl: config.apiUrl,
    isLocalDev: config.isLocalDev,
    nodeEnv: process.env.NODE_ENV,
  };

  // Always log in development
  if (process.env.NODE_ENV === 'development') {
    console.log('[Auth Config] Current Configuration:', configLog);
  }

  // Critical errors should be logged in all environments
  if (!validation.isValid) {
    console.error('[Auth Config] ❌ VALIDATION FAILED:', validation.errors);

    // In production, also log build-time issue detection
    if (validation.buildTimeIssueDetected && process.env.NODE_ENV === 'production') {
      console.error(
        '[Auth Config] 🔴 BUILD-TIME CONFIGURATION ERROR DETECTED IN PRODUCTION!',
        'This should have been caught by the prebuild validator.'
      );
      console.error('[Auth Config] Configuration:', configLog);
    }
  }

  if (validation.warnings.length > 0) {
    if (process.env.NODE_ENV === 'development') {
      // Suppress warnings for localhost (inherently development environment)
      const isLocalhost = window.location.hostname === 'localhost' ||
                         window.location.hostname === '127.0.0.1';
      if (!isLocalhost) {
        console.warn('[Auth Config] ⚠️ Warnings:', validation.warnings);
      }
    }
  }

  if (validation.isValid && validation.warnings.length === 0) {
    if (process.env.NODE_ENV === 'development') {
      console.log('[Auth Config] ✅ Environment configuration is correct');
    }
  }

  return {
    isValid: validation.isValid,
    config,
    validation,
  };
}

/**
 * Check if a request is going to a different environment than the app
 * Useful for detecting cross-environment API calls
 */
export function detectCrossEnvironmentCall(url: string): {
  isCrossEnvironment: boolean;
  message?: string;
} {
  const config = getAuthEnvironmentConfig();

  // Extract environment from URL
  const urlMatch = url.match(/https:\/\/([^.]+)\./);
  const urlEnv = urlMatch ? urlMatch[1] : 'production';

  // Extract environment from auth config
  const authMatch = config.authUrl.match(/https:\/\/([^.]+)\./);
  const configEnv = authMatch ? authMatch[1] : 'production';

  if (urlEnv !== configEnv) {
    return {
      isCrossEnvironment: true,
      message: `Cross-environment call detected: ${urlEnv} URL requested from ${configEnv} environment`,
    };
  }

  return {
    isCrossEnvironment: false,
  };
}
